def _is_valid_email(value: str) -> bool:
    email = value.strip()
    if email.count("@") != 1:
        return False
    local, _, domain = email.partition("@")
    if not local:
        return False
    if "." not in domain:
        return False
    if domain.startswith(".") or domain.endswith("."):
        return False
    return True


